
.left {
    border-right: 1px solid var(--border);
    flex: 1.2;
}
.left-title {
    font-weight: 600;
    margin-bottom: 12px;
    font-size: 15px;
}
.column-list-scroll {
    overflow-y: auto;
    flex: 1;
    padding-right: 8px;
}
.column-checkbox-item {
    margin-bottom: 10px;
}
.checkbox-label {
    display: flex;
    align-items: center;
    gap: 8px;
    font-size: 14px;
    cursor: pointer;
}
.right {
    display: flex;
    flex-direction: column;
    flex: 1.8;
}
.right-title {
    font-weight: 600;
    margin-bottom: 12px;
    font-size: 15px;
}
.frozen-nonfrozen-wrap {
    display: flex;
    gap: 24px;
    height: 340px;
}
.frozen-list-wrap,
.nonfrozen-list-wrap {
    flex: 1;
    display: flex;
    flex-direction: column;
}
.frozen-title,
.nonfrozen-title {
    font-weight: 500;
    font-size: 14px;
    margin-bottom: 8px;
}
.frozen-columns-list,
.nonfrozen-columns-list {
    background: var(--muted);
    border-radius: 8px;
    border: 1px solid var(--border);
}
.selected-column-item {
    display: flex;
    align-items: center;
    background: var(--background);
    border: 1px solid var(--border);
    border-radius: 8px;
    padding: 4px 8px;
    font-size: 14px;
    gap: 10px;
    box-shadow: 0 1px 2px rgba(0, 0, 0, 0.03);
    position: relative;
}
.drag-handle {
    cursor: grab;
    font-size: 18px;
    color: var(--muted-foreground);
    margin-right: 6px;
}
.remove-btn {
    background: none;
    border: none;
    color: var(--destructive);
    font-size: 18px;
    margin-left: auto;
    cursor: pointer;
    padding: 0 4px;
}
.column-settings-actions {
    display: flex;
    justify-content: flex-end;
    gap: 12px;
    padding: 18px 32px 18px 0;
    border-top: 1px solid var(--border);
    background: var(--muted);
}
.apply-btn {
    background: var(--primary);
    color: var(--primary-foreground);
    border: none;
    border-radius: 4px;
    padding: 8px 20px;
    font-weight: 500;
    cursor: pointer;
}
.cancel-btn {
    background: var(--muted);
    color: var(--foreground);
    border: none;
    border-radius: 4px;
    padding: 8px 20px;
    cursor: pointer;
}
.grid-footer-sum {
    display: flex;
    align-items: center;
    background: var(--muted);
    border-top: 1px solid var(--border);
    font-weight: 600;
    color: var(--foreground);
    position: sticky;
    bottom: 0;
    z-index: 10;
    min-height: 60px;
}
.footer-cell {
    display: flex;
    align-items: center;
    justify-content: flex-end;
    padding: 0 12px;
    height: 100%;
    font-size: 14px;
    border-right: 1px solid var(--border);
    background: var(--muted);
}

.footer-text {
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
}
.group-footer {
    font-weight: 700;
    color: var(--primary);
    justify-content: flex-start;
}
.footer-cell.frozen-column {
    position: sticky;
    background: var(--muted);
    z-index: 100;
    left: 0;
    /* Có thể thêm border hoặc shadow nếu muốn nổi bật */
}
.header-cell,
.row-cell {
    /* border-top: 1px solid var(--border); */
}
.grid-header-container {
    position: sticky;
    top: 0;
    z-index: 10;
    background: var(--background);
    /* KHÔNG sticky theo chiều ngang, KHÔNG left/right */
}
.header-cell.frozen-column,
.row-cell.frozen-column {
    position: sticky;
    /* sticky chỉ theo left, không top */
    z-index: 100;
    /* box-shadow: 2px 0 4px -2px #e0e0e0; */
}
.header-cell.checkbox-cell.frozen-column,
.row-cell.checkbox-cell.frozen-column {
    position: sticky;
    left: 0;
    z-index: 110;
}
.cell-align-left {
    justify-content: flex-start !important;
    text-align: left !important;
}
.cell-align-center {
    justify-content: center !important;
    text-align: center !important;
}
.cell-align-right {
    justify-content: flex-end !important;
    text-align: right !important;
}

/* --- Virtual Non-Frozen Cells --- */
.non-frozen-cell {
    position: absolute !important;
    height: 100% !important;
    /* background: inherit !important; */
}

/* --- Resize Preview Line --- */
.resize-preview-line {
    position: absolute;
    top: 0;
    width: 1px;
    height: 100%;
    background: linear-gradient(to bottom, var(--primary), var(--primary));
    z-index: 1000;
    pointer-events: none;
}

.resize-preview-line::before {
    /* content: "";
    position: absolute;
    top: 0;
    left: -1px;
    right: -1px;
    height: 100%;
    background: rgba(51, 10, 255, 0.1); */
    /* border-left: 1px solid var(--primary);
    border-right: 1px solid var(--primary); */
}

/* --- Column Resizer Cursor --- */
.column-resizer {
    cursor: col-resize;
}

.column-resizer:hover {
    /* background-color: rgba(24, 144, 255, 0.1); */
}

/* Tab styles */
.tab-button {
    padding: 8px 16px;
    background-color: var(--muted);
    border: 1px solid var(--border);
    border-radius: 6px;
    font-size: 14px;
    font-weight: 500;
    cursor: pointer;
    transition: all 0.2s;
}

.tab-button:hover {
    background-color: var(--border);
}

.tab-button.active {
    background-color: var(--primary);
    color: white;
    border-color: var(--primary);
}

/* Group styles */
.group-drop-zone {
    transition: all 0.2s;
}

.group-drop-zone.drag-over {
    background-color: var(--accent);
    border-color: var(--primary);
}

.group-item {
    display: flex;
    align-items: center;
    background: var(--background);
    border: 1px solid var(--border);
    border-radius: 6px;
    padding: 8px 12px;
    margin-bottom: 8px;
    font-size: 14px;
    gap: 10px;
    box-shadow: 0 1px 2px rgba(0, 0, 0, 0.03);
}

.group-available-item {
    display: flex;
    align-items: center;
    background: var(--muted);
    border: 1px solid var(--border);
    border-radius: 6px;
    padding: 8px 12px;
    margin-bottom: 6px;
    font-size: 14px;
    gap: 10px;
    cursor: move;
    transition: all 0.2s;
}

.group-available-item:hover {
    background: var(--muted);
    border-color: var(--border);
}

/* Body cursor during resize */
body.resizing-column {
    cursor: col-resize !important;
    user-select: none;
}

.pivot-cell-content {
    display: flex;
    align-items: center;
    width: 100%;
    height: 100%;
}

.pivot-indent {
    display: inline-block;
    height: 100%;
    flex-shrink: 0;
}

.pivot-toggle-icon {
    display: inline-block;
    width: 20px;
    cursor: pointer;
    transition: transform 0.2s ease-in-out;
    user-select: none;
    flex-shrink: 0;
    text-align: center;
    color: var(--muted-foreground);
}

.pivot-toggle-icon.expanded {
    transform: rotate(90deg);
}

.pivot-summary-row .row-cell {
    /* font-weight: 600; */
    background-color: #f8f9fa; /* Màu nền cho hàng tổng hợp */
}

/* Pivot Column Settings Styles */
.pivot-section {
    margin-bottom: 20px;
}

.pivot-section-title {
    font-weight: 600;
    font-size: 14px;
    color: var(--foreground);
    margin-bottom: 8px;
    padding: 8px 0;
    border-bottom: 1px solid var(--border);
}

.pivot-selected-wrap {
    display: flex;
    flex-direction: column;
    gap: 20px;
    height: 340px;
}

.pivot-selected-section {
    flex: 1;
    display: flex;
    flex-direction: column;
}

.pivot-selected-title {
    font-weight: 500;
    font-size: 14px;
    margin-bottom: 8px;
    color: var(--foreground);
}

.pivot-selected-list {
    background: var(--muted);
    border-radius: 8px;
    border: 1px solid var(--border);
    min-height: 120px;
    max-height: 150px;
    overflow-y: auto;
    padding: 12px 0;
    flex: 1;
}

.selected-pivot-item {
    display: flex;
    align-items: center;
    background: var(--background);
    border: 1px solid var(--border);
    border-radius: 6px;
    margin: 0 16px 8px 16px;
    padding: 8px 12px;
    font-size: 14px;
    gap: 10px;
    box-shadow: 0 1px 2px rgba(0, 0, 0, 0.03);
    position: relative;
}

.selected-pivot-item .remove-btn {
    background: none;
    border: none;
    color: var(--destructive);
    font-size: 18px;
    margin-left: auto;
    cursor: pointer;
    padding: 0 4px;
}

.empty-space-cell {
    /* border: none !important; */
    pointer-events: none;
    flex-shrink: 0;
    border-top: 1px solid var(--border);
}

.header-empty-absolute {
    position: absolute !important;
    top: 0;
    bottom: 0;
    z-index: 1;
}

.zoom-icon {
    font-size: 16px;
}

/* Fullscreen styles */
.data-grid-container.fullscreen-mode {
    position: fixed;
    top: 0;
    left: 0;
    width: 100vw;
    height: 100vh;
    z-index: 9999;
    background: white;
    margin: 0;
    border: 0;
}

.data-grid-container.fullscreen-mode .data-grid-content {
    height: 100%;
}
