
.pagination {
  display: flex;
  align-items: center;
  min-height: 48px;
  padding: 8px 20px;
  color: #5e6360;
  font-size: 14px;
  line-height: 20px;
}

.pagination-control-group {
  display: flex;
  min-width: 0;
  align-items: center;
  gap: 12px;
}

.pagination-desc,
.pagination-total-muted {
  color: #a5aca7;
  font-weight: 400;
}

.pagination-select-trigger {
  width: 74px;
  height: 32px;
  border: 0;
  border-radius: 999px;
  background: #ffffff;
  color: #5e6360;
  box-shadow: none;
}

.pagination-nav-pill {
  display: inline-flex;
  height: 32px;
  align-items: center;
  gap: 2px;
  border-radius: 999px;
  background: #ffffff;
  padding: 0 6px;
  color: #1f2421;
}

.pagination-nav-button {
  display: inline-flex;
  width: 24px;
  height: 24px;
  align-items: center;
  justify-content: center;
  border: 0;
  border-radius: 999px;
  background: transparent;
  color: #1f2421;
  cursor: pointer;
  transition: background-color 0.15s ease, color 0.15s ease, opacity 0.15s ease;
}

.pagination-nav-button:not(:disabled):hover {
  background: #d8e9e1;
}

.pagination-disable {
  cursor: not-allowed;
  color: #a5aca7;
  opacity: 0.55;
}

.pagination-page-indicator {
  min-width: 42px;
  color: #1f2421;
  font-weight: 500;
  text-align: center;
}

.pagination-separator {
  width: 1px;
  height: 28px;
  background: rgba(165, 172, 167, 0.45);
}

.pagination-total {
  white-space: nowrap;
}

.pagination-total-strong {
  color: #1f2421;
  font-weight: 500;
}
