
.date-range-picker-trigger {
  flex: 0 0 auto;
}

.date-range-picker-trigger-active {
  color: #062 !important;
  box-shadow:
    0 0 0 2px rgba(60, 153, 68, 0.18),
    0 12px 26px rgba(0, 177, 115, 0.16) !important;
}

.date-range-picker-caret {
  position: absolute;
  top: -7px;
  right: 18px;
  width: 14px;
  height: 14px;
  transform: rotate(45deg);
  border-top: 1px solid #bfd8cc;
  border-left: 1px solid #bfd8cc;
  background: #f8fffa;
}

.date-range-picker-body {
  display: grid;
  grid-template-columns: 150px minmax(0, 1fr);
  min-height: 328px;
}

.date-range-picker-presets {
  display: flex;
  max-height: 328px;
  flex-direction: column;
  overflow-y: auto;
  border-right: 1px solid #d8e9e1;
  padding: 8px;
}

.date-range-picker-preset {
  min-height: 38px;
  border: 0;
  border-radius: 12px;
  background: transparent;
  padding: 0 12px;
  color: #3f4742;
  font-size: 13px;
  font-weight: 500;
  text-align: left;
  transition: background 120ms ease, color 120ms ease, box-shadow 120ms ease;
}

.date-range-picker-preset:hover {
  background: #e8f7ee;
  color: #1f2a24;
}

.date-range-picker-preset-active,
.date-range-picker-preset-active:hover {
  background: linear-gradient(270deg, #7cd249 0%, #339d36 100%);
  color: #ffffff;
  box-shadow: 0 8px 18px rgba(0, 102, 34, 0.16);
}

.date-range-picker-calendars {
  position: relative;
  min-width: 0;
  padding: 16px 16px 14px;
}

.date-range-picker-month-nav {
  pointer-events: none;
  position: absolute;
  inset: 14px 10px auto;
  z-index: 1;
  display: flex;
  justify-content: space-between;
}

.date-range-picker-nav-button {
  pointer-events: auto;
  display: inline-flex;
  width: 28px;
  height: 28px;
  align-items: center;
  justify-content: center;
  border: 0;
  border-radius: 999px;
  background: transparent;
  color: #3f4742;
  font-size: 26px;
  font-weight: 600;
  line-height: 1;
}

.date-range-picker-nav-button:hover {
  background: #d8e9e1;
  color: #062;
}

.date-range-picker-months {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 14px;
}

.date-range-picker-month-title {
  margin: 0 0 12px;
  color: #1f2a24;
  font-size: 15px;
  font-weight: 600;
  text-align: center;
}

.date-range-picker-weekdays,
.date-range-picker-grid {
  display: grid;
  grid-template-columns: repeat(7, minmax(24px, 1fr));
}

.date-range-picker-weekdays {
  margin-bottom: 4px;
  color: #5e6360;
  font-size: 11px;
  font-weight: 600;
  text-align: center;
}

.date-range-picker-weekdays span {
  padding: 4px 0;
}

.date-range-picker-day {
  position: relative;
  display: inline-flex;
  min-height: 28px;
  align-items: center;
  justify-content: center;
  border: 0;
  background: transparent;
  color: #1f2a24;
  font-size: 12px;
  font-weight: 500;
}

.date-range-picker-day:hover {
  background: #e8f7ee;
}

.date-range-picker-day-muted {
  color: #a5aca7;
}

.date-range-picker-day-in-range {
  background: #e1faf2;
}

.date-range-picker-day-start,
.date-range-picker-day-end,
.date-range-picker-day-start:hover,
.date-range-picker-day-end:hover {
  background: #3c9944;
  color: #ffffff;
  font-weight: 600;
}

.date-range-picker-day-start {
  border-radius: 8px 0 0 8px;
}

.date-range-picker-day-end {
  border-radius: 0 8px 8px 0;
}

.date-range-picker-day-start.date-range-picker-day-end {
  border-radius: 8px;
}

.date-range-picker-footer {
  display: flex;
  min-height: 58px;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  border-top: 1px solid #d8e9e1;
  padding: 10px 14px;
}

.date-range-picker-selected-label {
  margin: 0;
  border-radius: 999px;
  background: #f3f7f5;
  padding: 8px 12px;
  color: #3f4742;
  font-size: 13px;
  font-weight: 500;
}

.date-range-picker-actions {
  display: flex;
  align-items: center;
  gap: 10px;
}

.date-range-picker-cancel {
  min-height: 34px;
  border: 0;
  border-radius: 999px;
  background: transparent;
  padding: 0 14px;
  color: #3f4742;
  font-size: 13px;
  font-weight: 600;
}

.date-range-picker-cancel:hover {
  background: #d8e9e1;
  color: #062;
}

.date-range-picker-apply {
  min-width: 76px;
  min-height: 34px;
  border: 0 !important;
  border-radius: 999px !important;
  background: linear-gradient(270deg, #7cd249 0%, #339d36 100%) !important;
  padding: 8px 16px !important;
  color: #ffffff !important;
  box-shadow: 0 10px 22px rgba(0, 102, 34, 0.16) !important;
  font-size: 13px;
  font-weight: 600;
}

@media (max-width: 760px) {
  .date-range-picker-body {
    grid-template-columns: 1fr;
  }

  .date-range-picker-presets {
    max-height: none;
    flex-direction: row;
    overflow-x: auto;
    border-right: 0;
    border-bottom: 1px solid #d8e9e1;
  }

  .date-range-picker-preset {
    min-width: max-content;
  }

  .date-range-picker-months {
    grid-template-columns: 1fr;
  }

  .date-range-picker-footer {
    align-items: flex-start;
    flex-direction: column;
  }
}
