
/* Component specific styles can go here if needed */
.column-settings-modal {
    position: fixed;
    top: 50%;
    left: 50%;
    transform: translate(-50%, -50%);
    background: transparent;
    border-radius: 10px;
    box-shadow: 0 2px 24px rgba(0, 0, 0, 0.18);
    padding: 0;
    z-index: 1000;
    min-width: 700px;
    min-height: 480px;
    display: flex;
    flex-direction: column;
}
.popup-columns {
    display: flex;
    gap: 0;
    height: 500px;
}
.left {
    flex: 1.2;
    border-right: 1px solid var(--border);
    padding: 24px 0 24px 24px;
    display: flex;
    flex-direction: column;
}
.left-title {
    font-weight: 600;
    margin-bottom: 12px;
    font-size: 15px;
}
.column-list-scroll {
    overflow-y: auto;
    flex: 1;
    padding-right: 8px;
}
.column-checkbox-item {
    margin-bottom: 10px;
}
.checkbox-label {
    display: flex;
    align-items: center;
    gap: 8px;
    font-size: 14px;
    cursor: pointer;
}
.right {
    flex: 1.8;
    padding: 24px;
    display: flex;
    flex-direction: column;
}
.right-title {
    font-weight: 600;
    margin-bottom: 12px;
    font-size: 15px;
}
.frozen-nonfrozen-wrap {
    display: flex;
    gap: 24px;
    height: 340px;
}
.frozen-list-wrap,
.nonfrozen-list-wrap {
    flex: 1;
    display: flex;
    flex-direction: column;
}
.frozen-title,
.nonfrozen-title {
    font-weight: 500;
    font-size: 14px;
    margin-bottom: 8px;
}
.frozen-columns-list,
.nonfrozen-columns-list {
    background: transparent;
    border-radius: 8px;
    border: 1px solid var(--border);
    min-height: 260px;
    max-height: 320px;
    overflow-y: auto;
    padding: 12px 0;
}
.selected-column-item {
    display: flex;
    align-items: center;
    background: transparent;
    border: 1px solid var(--border);
    border-radius: 6px;
    margin: 0 16px 10px 16px;
    padding: 8px 12px;
    font-size: 14px;
    gap: 10px;
    box-shadow: 0 1px 2px rgba(0, 0, 0, 0.03);
    position: relative;
}
.drag-handle {
    cursor: grab;
    font-size: 18px;
    color: var(--muted-foreground);
    margin-right: 6px;
}
.remove-btn {
    background: none;
    border: none;
    color: var(--destructive);
    font-size: 18px;
    margin-left: auto;
    cursor: pointer;
    padding: 0 4px;
}
.column-settings-actions {
    display: flex;
    justify-content: flex-end;
    gap: 12px;
    padding: 18px 32px 18px 0;
    border-top: 1px solid var(--border);
    background: transparent;
}
.apply-btn {
    background: var(--primary);
    color: var(--primary-foreground);
    border: none;
    border-radius: 4px;
    padding: 8px 20px;
    font-weight: 500;
    cursor: pointer;
}
.cancel-btn {
    background: transparent;
    color: var(--foreground);
    border: none;
    border-radius: 4px;
    padding: 8px 20px;
    cursor: pointer;
}
.grid-footer-sum {
    display: flex;
    align-items: center;
    background: transparent;
    border-top: 1px solid var(--table-border-color);
    font-weight: 600;
    color: var(--foreground);
    position: sticky;
    bottom: 0;
    z-index: 10;
    min-height: 60px;
}
.footer-cell {
    display: flex;
    align-items: center;
    justify-content: flex-end;
    padding: 0 12px;
    height: 100%;
    font-size: 14px;
    border-right: 1px solid var(--table-column-border-color);
    background: transparent;
}

.footer-text {
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
}
.footer-cell.frozen-column {
    position: sticky;
    background: var(--table-pane-surface);
    z-index: 100;
    left: 0;
    /* Có thể thêm border hoặc shadow nếu muốn nổi bật */
}
.header-cell,
.row-cell {
    /* border-top: 1px solid #f0f0f0; */
}
.grid-header-container {
    position: sticky;
    top: 0;
    z-index: 10;
    background: transparent;
    /* KHÔNG sticky theo chiều ngang, KHÔNG left/right */
}
.header-cell.frozen-column,
.row-cell.frozen-column {
    position: sticky;
    /* sticky chỉ theo left, không top */
    z-index: 100;
    /* box-shadow: 2px 0 4px -2px #e0e0e0; */
}
.header-cell.checkbox-cell.frozen-column,
.row-cell.checkbox-cell.frozen-column {
    position: sticky;
    left: 0;
    z-index: 110;
}
.row-cell.last-frozen-column,
.footer-cell.last-frozen-column {
    overflow: visible;
}
.row-cell.show-shadow.last-frozen-column::after,
.footer-cell.show-shadow.last-frozen-column::after {
    width: 5px;
}
.row-cell.last-frozen-column::after,
.footer-cell.last-frozen-column::after {
    content: "";
    height: 100%;
    position: absolute;
    right: -1px;
    width: 0px;
    transform: translateX(100%);
    transition: all 0.3s;
    pointer-events: none;
    background: 0 0 url(data:image/png;base64,iVBORw0KGgoAAAANSUhEUgAAAAQAAAABCAYAAAD5PA/NAAAAFklEQVQIHWPSkNeSBmJhTQVtbiDNCgASagIIuJX8OgAAAABJRU5ErkJggg==) repeat-y;
}

.cell-align-left {
    justify-content: flex-start !important;
    text-align: left !important;
}
.cell-align-center {
    justify-content: center !important;
    text-align: center !important;
}
.cell-align-right {
    justify-content: flex-end !important;
    text-align: right !important;
}

/* --- Virtual Non-Frozen Cells --- */
.non-frozen-cell {
    position: absolute !important;
    height: 100% !important;
}

/* --- Resize Preview Line --- */
.resize-preview-line {
    position: absolute;
    top: 0;
    width: 2px;
    height: 100%;
    background: var(--primary);
    border-radius: 1px;
    box-shadow: 0 0 4px color-mix(in oklab, var(--primary) 60%, transparent);
    z-index: 1000;
    pointer-events: none;
}

/* Live size tooltip pinned to the top of the preview line. */
.resize-tooltip {
    position: absolute;
    top: 4px;
    left: 50%;
    transform: translateX(-50%);
    padding: 2px 6px;
    background: var(--primary);
    color: var(--primary-foreground);
    font-size: 11px;
    font-weight: 600;
    line-height: 1.4;
    border-radius: 4px;
    white-space: nowrap;
    pointer-events: none;
}

/* Highlight the header of the column currently being resized. */
.header-cell.is-resizing-target {
    background: color-mix(in oklab, var(--primary) 8%, transparent);
}

/* Ghost line at the frozen-column max width — shown for the whole drag so the
   user sees the limit before reaching it. */
.resize-max-line {
    position: absolute;
    top: 0;
    bottom: 0;
    width: 0;
    border-left: 1px dashed color-mix(in oklab, var(--destructive) 70%, transparent);
    z-index: 999;
    pointer-events: none;
}

/* When the drag is clamped at the limit, the preview + tooltip turn destructive. */
.resize-preview-line.is-at-max {
    background: var(--destructive);
    box-shadow: 0 0 4px color-mix(in oklab, var(--destructive) 60%, transparent);
}

.resize-tooltip.is-at-max {
    background: var(--destructive);
    /* No --destructive-foreground token in the apps; white reads on the red bg. */
    color: var(--destructive-foreground, #fff);
}

/* Body cursor during resize */
body.resizing-column {
    cursor: col-resize !important;
    user-select: none;
}

.field-chip {
    cursor: move;
    transition: all 0.2s ease;
    width: 100%;
}

.field-chip:hover {
    background-color: var(--border);
}

.field-chip.dragging {
    opacity: 0.5;
    background: var(--primary);
}

.drag-handle {
    cursor: grab;
}

.drag-handle:active {
    cursor: grabbing;
}

.pivot-cell-content {
    display: flex;
    align-items: center;
    width: 100%;
    height: 100%;
}

.pivot-indent {
    display: inline-block;
    height: 100%;
    flex-shrink: 0;
}

.pivot-toggle-icon {
    display: inline-block;
    width: 20px;
    cursor: pointer;
    transition: transform 0.2s ease-in-out;
    user-select: none;
    flex-shrink: 0;
    text-align: center;
    color: var(--muted-foreground);
}

.pivot-toggle-icon.expanded {
    transform: rotate(90deg);
}

.pivot-summary-row .row-cell {
    /* font-weight: 600; */
    background-color: transparent; /* summary rows follow the transparent table surface */
}

/* Pivot Column Settings Styles */
.pivot-section {
    margin-bottom: 20px;
}

.pivot-section-title {
    font-weight: 600;
    font-size: 14px;
    color: var(--foreground);
    margin-bottom: 8px;
    padding: 8px 0;
    border-bottom: 1px solid var(--border);
}

.pivot-selected-wrap {
    display: flex;
    flex-direction: column;
    gap: 20px;
    height: 340px;
}

.pivot-selected-section {
    flex: 1;
    display: flex;
    flex-direction: column;
}

.pivot-selected-title {
    font-weight: 500;
    font-size: 14px;
    margin-bottom: 8px;
    color: var(--foreground);
}

.pivot-selected-list {
    background: transparent;
    border-radius: 8px;
    border: 1px solid var(--border);
    min-height: 120px;
    max-height: 150px;
    overflow-y: auto;
    padding: 12px 0;
    flex: 1;
}

.selected-pivot-item {
    display: flex;
    align-items: center;
    background: transparent;
    border: 1px solid var(--border);
    border-radius: 6px;
    margin: 0 16px 8px 16px;
    padding: 8px 12px;
    font-size: 14px;
    gap: 10px;
    box-shadow: 0 1px 2px rgba(0, 0, 0, 0.03);
    position: relative;
}

.selected-pivot-item .remove-btn {
    background: none;
    border: none;
    color: var(--destructive);
    font-size: 18px;
    margin-left: auto;
    cursor: pointer;
    padding: 0 4px;
}

.empty-space-cell {
    /* border: none !important; */
    pointer-events: none;
    flex-shrink: 0;
    border-top: 1px solid var(--table-border-color);
}

.header-empty-absolute {
    position: absolute !important;
    top: 0;
    bottom: 0;
    z-index: 1;
}

.zoom-icon {
    font-size: 16px;
}

/* Fullscreen styles */
.data-grid-container.fullscreen-mode {
    position: fixed;
    top: 0;
    left: 0;
    width: 100vw;
    height: 100vh;
    z-index: 49;
    background: transparent;
    margin: 0;
    border: 0;
}

.data-grid-container.fullscreen-mode .data-grid-content {
    height: 100%;
}
